#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum KeymapOperation {
    Command,
    Unmap,
    Disable,
    PassThrough,
}

impl KeymapOperation {
    const fn as_str(self) -> &'static str {
        match self {
            Self::Command => "command",
            Self::Unmap => "unmap",
            Self::Disable => "disable",
            Self::PassThrough => "pass_through",
        }
    }
}

