    #[test]
    fn stale_generation_cleanup_preserves_replacement_ui_events() {
        let mut app = app();
        let event = |token| crate::plugins::PluginUiEvent {
            token,
            handle: None,
            graph_revision: None,
            tree_revision: None,
            surface_revision: None,
            geometry: None,
            action: None,
            error: None,
        };
        app.pending_plugin_ui_events
            .insert(("demo".into(), PluginLoadId(77)), vec![event(1)]);
        app.pending_plugin_ui_events
            .insert(("demo".into(), PluginLoadId(78)), vec![event(2)]);
        let storage_result = |load, token| crate::plugins::PluginStorageResult {
            plugin: "demo".into(),
            load: PluginLoadId(load),
            token,
            value: None,
            revision: None,
            entries: Vec::new(),
            truncated: false,
            error: None,
        };
        app.pending_plugin_storage_results.insert(
            ("demo".into(), PluginLoadId(77)),
            vec![storage_result(77, 1)],
        );
        app.pending_plugin_storage_results.insert(
            ("demo".into(), PluginLoadId(78)),
            vec![storage_result(78, 2)],
        );
        app.plugin_storage
            .install_generation("demo", PluginLoadId(78));
        let manifest = plugin_manifest("demo", "plugin.demo.keymap.dashboard", "x y");
        let replacement = crate::plugins::index_manifest_contributions(
            &manifest,
            78,
            "replacement manifest".into(),
        )
        .expect("replacement index");
        app.plugin_contributions
            .install(replacement)
            .expect("replacement catalog");
        app.remove_plugin_contribution_generation("demo", PluginLoadId(77));
        assert!(
            !app.pending_plugin_ui_events
                .contains_key(&("demo".into(), PluginLoadId(77)))
        );
        assert_eq!(
            app.pending_plugin_ui_events
                .get(&("demo".into(), PluginLoadId(78)))
                .and_then(|events| events.first())
                .map(|event| event.token),
            Some(2)
        );
        assert_eq!(
            app.plugin_contributions
                .get("demo")
                .map(|index| index.generation),
            Some(78)
        );
        assert!(
            !app.pending_plugin_storage_results
                .contains_key(&("demo".into(), PluginLoadId(77)))
        );
        assert_eq!(
            app.pending_plugin_storage_results
                .get(&("demo".into(), PluginLoadId(78)))
                .and_then(|results| results.first())
                .map(|result| result.token),
            Some(2)
        );
    }

    #[test]
    fn expected_index_failure_before_sibling_index_aborts_the_complete_batch() {
        let mut app = app();
        app.configuration.deferred_plugin_keymaps = true;
        app.configuration.expected_plugin_indexes =
            ["bad".to_owned(), "good".to_owned()].into_iter().collect();
        let bad = tempfile::tempdir().expect("bad plugin store");
        fs::write(bad.path().join("manifest.toml"), "not = [valid").expect("bad manifest");
        let good = tempfile::tempdir().expect("good plugin store");
        write_plugin_manifest(
            good.path(),
            &plugin_manifest("good", "plugin.good.keymap.dashboard", "x y"),
        );
        let limits = app.plugin_limits();
        let bad_load = app
            .plugins
            .index_from_store(
                "bad".into(),
                bad.path().to_path_buf(),
                PathBuf::from("manifest.toml"),
                PathBuf::from("missing.wasm"),
                limits.clone(),
            )
            .expect("bad index request");
        let good_load = app
            .plugins
            .index_from_store(
                "good".into(),
                good.path().to_path_buf(),
                PathBuf::from("manifest.toml"),
                PathBuf::from("missing.wasm"),
                limits,
            )
            .expect("good index request");
        let deadline = Instant::now() + Duration::from_secs(2);
        while app.plugins.load_id("good").is_some()
            || app.plugins.load_id("bad").is_some()
            || !app.pending_index_activation.is_empty()
        {
            app.process_plugin_events();
            assert!(Instant::now() < deadline, "batch rejection timed out");
            thread::yield_now();
        }
        app.process_plugin_events();
        assert!(app.plugin_contributions.get("bad").is_none());
        assert!(app.plugin_contributions.get("good").is_none());
        assert!(
            app.configuration
                .keymaps
                .inspect_id("plugin.good.keymap.dashboard")
                .is_none()
        );
        assert!(app.pending_index_activation.is_empty());
        assert!(!app.plugins.is_active_generation("bad", bad_load));
        assert!(!app.plugins.is_active_generation("good", good_load));
    }

    #[test]
    fn deferred_user_plugin_move_compiles_after_index_then_falls_back_after_activation_failure() {
        let mut app = app();
        let root = tempfile::tempdir().expect("plugin store");
        write_plugin_manifest(
            root.path(),
            &plugin_manifest("demo", "plugin.demo.keymap.dashboard", "x y"),
        );
        let mut loaded = crate::configuration::load_bundled_config();
        loaded.config.plugins.entries.insert(
            "demo".into(),
            crate::configuration::PluginEntryConfig {
                manifest: PathBuf::from("manifest.toml"),
                component: PathBuf::from("missing.wasm"),
                enabled: true,
            },
        );
        loaded.config.windows.rules = vec![crate::configuration::WindowRuleConfig {
            content_type: "plugin.demo.panel".into(),
            placement: crate::configuration::WindowPlacementConfig::Floating {
                x: 4,
                y: 3,
                width: 50,
                height: 12,
            },
        }];
        loaded.keymaps.entries.extend([
            crate::configuration::KeymapEntry {
                id: "plugin.demo.keymap.dashboard".into(),
                context: Some("dashboard".into()),
                mode: String::new(),
                keys: Some("z".into()),
                command: Some("plugin.demo.run".into()),
                arguments: BTreeMap::new(),
                unmap: false,
                disable: false,
                pass_through: false,
            },
            crate::configuration::KeymapEntry {
                id: "user.test.demo-retained-next".into(),
                context: Some("plugin.demo.chat".into()),
                mode: String::new(),
                keys: Some("j".into()),
                command: Some("surface.retained.focus.next".into()),
                arguments: BTreeMap::new(),
                unmap: false,
                disable: false,
                pass_through: false,
            },
        ]);
        let (configuration, diagnostic) =
            super::resolve_configuration(&app.commands, loaded, true).expect("deferred config");
        assert!(diagnostic.is_none());
        assert!(configuration.deferred_plugin_keymaps);
        assert!(configuration.settings.windows.rules.is_empty());
        assert_eq!(configuration.raw_windows.rules.len(), 1);
        app.configuration = configuration;
        let load = app
            .plugins
            .index_from_store(
                "demo".into(),
                root.path().to_path_buf(),
                PathBuf::from("manifest.toml"),
                PathBuf::from("missing.wasm"),
                app.plugin_limits(),
            )
            .expect("index request");
        let deadline = Instant::now() + Duration::from_secs(2);
        while app.plugin_contributions.get("demo").is_none() {
            app.process_plugin_events();
            assert!(Instant::now() < deadline, "static acceptance timed out");
            thread::yield_now();
        }
        let moved = app
            .configuration
            .keymaps
            .inspect_id("plugin.demo.keymap.dashboard")
            .expect("user replacement");
        assert_eq!(moved.keys, "z");
        assert_eq!(moved.contribution_layer, InputContextLayer::User);
        assert_eq!(
            app.configuration
                .keymaps
                .inspect_id("user.test.demo-retained-next")
                .map(|mapping| mapping.context),
            Some("plugin.demo.chat".into())
        );
        assert_eq!(
            app.configuration.settings.windows.rules[0].content_type,
            "plugin.demo.panel"
        );
        assert!(
            app.configuration
                .keymaps
                .inspect_key("dashboard", "x y")
                .is_none()
        );
        while app.plugin_contributions.get("demo").is_some() {
            app.process_plugin_events();
            assert!(Instant::now() < deadline, "activation rollback timed out");
            thread::yield_now();
        }
        assert!(!app.plugins.is_active_generation("demo", load));
        assert!(
            app.configuration
                .keymaps
                .inspect_id("plugin.demo.keymap.dashboard")
                .is_none()
        );
        assert!(
            app.configuration
                .keymaps
                .inspect_id("user.test.demo-retained-next")
                .is_none()
        );
        assert!(app.configuration.settings.windows.rules.is_empty());
    }

